<?php
require_once __DIR__ . '/includes/functions.php';
$slug = trim($_GET['slug'] ?? ''); $stmt = db()->prepare("SELECT * FROM salons WHERE slug = ? AND status = 'approved'"); $stmt->execute([$slug]); $salon = $stmt->fetch();
if (!$salon) { http_response_code(404); exit('Salon not found'); }
$servicesStmt = db()->prepare("SELECT s.*, c.name category FROM services s LEFT JOIN service_categories c ON c.id=s.category_id WHERE s.salon_id=? AND s.status='active' ORDER BY s.id"); $servicesStmt->execute([$salon['id']]); $services = $servicesStmt->fetchAll();
$staffStmt = db()->prepare("SELECT * FROM staff WHERE salon_id=? AND status='active' ORDER BY name"); $staffStmt->execute([$salon['id']]); $staff = $staffStmt->fetchAll();
$page_title = $salon['name']; include __DIR__ . '/includes/header.php';
