lass="d-flex align-items-center gap-3 mt-3"><div class="avatar"><?= e(initials($person['name'])) ?></div><div><strong><?= e($person['name']) ?></strong><small class="d-block muted"><?= e($person['specialization']) ?></small></div></div><?php endforeach; ?></div></aside></div></div></main><?php include __DIR__ . '/includes/footer.php'; ?>
